<script setup>
defineProps({ entries:{type:Array,default:()=>[]}, datasources:{type:Array,default:()=>[]}, datasource:{type:String,default:''}, draft:{type:Object,required:true}, editingId:{type:[String,Number],default:''}, history:{type:Array,default:()=>[]}, historyId:{type:String,default:''}, error:{type:String,default:''}, loading:{type:Boolean,default:false}, busy:{type:Boolean,default:false} })
const emit = defineEmits(['update:datasource','refresh','select-datasource','save','edit','history','remove','cancel','back'])
const kinds = [['metric','指标'],['alias','字段别名'],['value_dictionary','字段值词典'],['relationship','关联路径'],['default_filter','默认过滤'],['sensitive_field','敏感字段'],['sql_example','SQL 示例']]
function kindLabel(value){ return kinds.find(item=>item[0]===value)?.[1] || value }
function definitionPreview(value){ try{return JSON.stringify(value || {})}catch{return '{}'} }
</script>
<template>
  <main class="admin semantics-page">
    <header><div><span class="eyebrow">SEMANTIC CATALOG</span><h1>企业语义层</h1><p>维护查询规划使用的指标、别名、受控字段值、关联关系、默认过滤与敏感字段。</p></div><div class="head-actions"><button class="ghost" :disabled="loading" @click="emit('refresh')">刷新</button><button class="run" @click="emit('back')">← 返回查询</button></div></header>
    <section class="semantic-toolbar card"><label>数据源<select :value="datasource" :disabled="loading || busy" @change="emit('update:datasource',$event.target.value);emit('select-datasource')"><option v-for="item in datasources" :key="item.id" :value="item.id">{{item.name}}（{{item.id}}）</option></select></label><span class="muted">{{loading?'正在加载…':`${entries.length} 个条目`}}</span></section>
    <div v-if="error" class="error">{{error}}</div>
    <div class="semantic-layout">
      <section class="card semantic-form-card"><div class="semantic-card-head"><h3>{{editingId?'编辑语义条目':'新增语义条目'}}</h3><button v-if="editingId" class="ghost" @click="emit('cancel')">取消编辑</button></div><form class="semantic-form" @submit.prevent="emit('save')"><label>类型<select v-model="draft.kind"><option v-for="item in kinds" :key="item[0]" :value="item[0]">{{item[1]}}</option></select></label><label>名称<input v-model="draft.name" maxlength="120" autocomplete="off" placeholder="例如 revenue 或 营收"></label><label>说明<input v-model="draft.description" maxlength="2000" autocomplete="off" placeholder="业务口径与适用范围"></label><label v-if="draft.kind!=='value_dictionary'">同义词<input v-model="draft.aliases" maxlength="500" autocomplete="off" placeholder="如 营收、销售收入"></label><label>检索关键词<input v-model="draft.keywords" maxlength="500" autocomplete="off" placeholder="如 区域、汇总、趋势"></label><label>JSON 定义<textarea v-model="draft.definition" spellcheck="false" :placeholder="draft.kind==='value_dictionary' ? '{\n  &quot;target_table&quot;: &quot;sales&quot;,\n  &quot;target_column&quot;: &quot;region&quot;,\n  &quot;tables&quot;: [&quot;sales&quot;],\n  &quot;columns&quot;: [&quot;region&quot;],\n  &quot;values&quot;: [{&quot;value&quot;: &quot;EAST&quot;, &quot;aliases&quot;: [&quot;华东&quot;]}]\n}' : '{}'"></textarea></label><button class="run" type="submit" :disabled="busy || !datasource">{{busy?'保存中…':editingId?'保存修改':'新增条目'}}</button></form></section>
      <section class="card semantic-list-card"><h3>语义目录</h3><div v-if="loading" class="semantic-empty">正在加载语义目录…</div><div v-else-if="!datasource" class="semantic-empty">当前没有可管理的数据源。</div><div v-else-if="!entries.length" class="semantic-empty">当前数据源暂无语义条目。</div><div v-else class="semantic-list"><article v-for="entry in entries" :key="entry.id" class="semantic-entry"><div class="semantic-entry-main"><div><span class="semantic-kind">{{kindLabel(entry.kind)}}</span><strong>{{entry.name}}</strong><small>v{{entry.version}} · {{entry.owner_id || 'system'}}</small></div><p v-if="entry.description" class="muted">{{entry.description}}</p><code>{{definitionPreview(entry.definition)}}</code><div v-if="historyId===entry.id" class="semantic-history"><span v-for="item in history" :key="item.id">v{{item.version}} · {{item.created_at.slice(0,19).replace('T',' ')}}</span></div></div><div class="row-actions"><button :disabled="busy" @click="emit('history',entry)">历史</button><button :disabled="busy" @click="emit('edit',entry)">编辑</button><button class="danger" :disabled="busy" @click="emit('remove',entry)">停用</button></div></article></div></section>
    </div>
  </main>
</template>
